  "Deleted user": "Utilisateur supprimé",
  "Deleting your account signs you out everywhere right away. After 14 days your profile, email, friends and private data are permanently deleted. Messages you sent in shared chats stay as “Deleted user”. Signing in again within 14 days cancels the deletion.": "Supprimer ton compte te déconnecte immédiatement partout. Après 14 jours, ton profil, ton adresse e-mail, tes amis et tes données privées sont définitivement supprimés. Les messages que tu as envoyés dans des chats partagés restent affichés sous « Utilisateur supprimé ». Te reconnecter dans les 14 jours annule la suppression.",
