  "Descall was founded by Demir Sarp Kurtlar, who remains the owner and CEO.": "Descall a été fondé par Demir Sarp Kurtlar, qui en reste le propriétaire et le PDG.",
  "Descall wins for squads that want DMs, groups, WebRTC voice/video, and screen share without Nitro. It is not trying to replace every public Discord server.": "Descall l'emporte pour les squads qui veulent des MP, des groupes, du vocal/vidéo WebRTC et le partage d'écran sans Nitro. Il ne cherche pas à remplacer chaque serveur Discord public.",
