  "Frequently asked questions": "Questions fréquentes",
  "Frequently asked questions about Descall, accounts, desktop download, calls, screen share, and privacy.": "Questions fréquentes sur Descall : comptes, téléchargement de l'appli de bureau, appels, partage d'écran et confidentialité.",
  "Friend": "Ami",
  "Friend Request": "Demande d'ami",
  "Friend Request Notifications": "Notifications de demandes d'ami",
  "Friend Requests": "Demandes d'ami",
  "Friend action failed.": "L'action sur l'ami a échoué.",
  "Friend groups": "Groupes d'amis",
  "Friend groups often pay for Nitro out of habit. Core voice and screen share should not require a subscription, that’s the promise of a free Discord alternative like Descall.": "Les groupes d'amis paient souvent Nitro par habitude. Le vocal et le partage d'écran de base ne devraient pas nécessiter d'abonnement : c'est la promesse d'une alternative gratuite à Discord comme Descall.",
  "Friend groups outgrow Discord chrome": "Les groupes d'amis dépassent l'interface chargée de Discord",
  "Friend groups, gaming squads, and small-to-mid communities that need servers, roles, voice, and screen share often prefer Descall as a lighter Discord alternative. Keep Discord if you still rely on huge bot ecosystems.": "Les groupes d'amis, les squads de gamers et les communautés petites à moyennes qui ont besoin de serveurs, de rôles, de vocal et de partage d'écran préfèrent souvent Descall, une alternative plus légère à Discord. Garde Discord si tu dépends encore d'énormes écosystèmes de bots.",
  "Friend invite": "Invitation d'ami",
  "Friend list, online status, and invites, jump from DMs into a server voice channel in one flow.": "Liste d'amis, statut en ligne et invitations : passe des MP à un salon vocal de serveur en un seul geste.",
  "Friend online notifications": "Notifications de connexion des amis",
  "Friend presence, activity status, and quick voice with your squad.": "Présence des amis, statut d'activité et vocal rapide avec ta squad.",
  "Friend request accepted": "Demande d'ami acceptée",
  "Friend requests, blocking, and presence/status": "Demandes d'ami, blocage et présence/statut",
  "Friend requests, online presence, and quick invites so your squad can jump into chat or voice.": "Demandes d'ami, présence en ligne et invitations rapides pour que ta squad rejoigne le chat ou le vocal.",
  "Friend voice + servers → Descall. Huge community → Discord. Pure voice server → TeamSpeak. Read our compare page before you force a full migration.": "Vocal entre amis + serveurs → Descall. Énorme communauté → Discord. Serveur purement vocal → TeamSpeak. Lis notre page de comparaison avant d'imposer une migration complète.",
  "Friend-group chat and voice without Nitro friction": "Chat et vocal entre amis sans la contrainte de Nitro",
  "Friends": "Amis",
  "Friends & presence": "Amis et présence",
  "Friends Only": "Amis uniquement",
  "Friends and presence": "Amis et présence",
  "Friends and presence inside Descall": "Amis et présence dans Descall",
  "Friends can see your activity": "Tes amis peuvent voir ton activité",
  "Friends hangout": "Repaire entre amis",
  "Friends list, ready for a lobby or a call": "Liste d'amis, prête pour un lobby ou un appel",
  "Friends usually want three things: who’s online, a place to chat, and a fast call button. Descall focuses on that private community loop, without forcing you to administer roles for a five-person squad.": "Les amis veulent en général trois choses : savoir qui est en ligne, un endroit pour discuter et un bouton d'appel rapide. Descall se concentre sur cette boucle de communauté privée, sans t'obliger à gérer des rôles pour une squad de cinq.",
  "Friends · DMs · Groups": "Amis · MP · Groupes",
  "Friends' active sessions will appear here": "Les sessions actives de tes amis apparaîtront ici",
