  "More options": "Plus d'options",
  "More reactions": "Plus de réactions",
  "Most Discord replacement attempts fail when voice feels worse. Descall invests in WebRTC calls, TURN, and screen-share presets so nightly voice stays easy.": "La plupart des tentatives de remplacer Discord échouent quand le vocal est moins bon. Descall investit dans les appels WebRTC, TURN et les préréglages de partage d'écran pour que le vocal du soir reste simple.",
  "Most community platforms either drown you in mega-server chrome or skip structure entirely. Descall gives you real servers with categories, text/voice/stage channels, roles, channel overrides, and ready-made community templates, so a clan, class, or creator circle can launch organized in minutes.": "La plupart des plateformes communautaires te noient sous l'interface des méga-serveurs ou font complètement l'impasse sur la structure. Descall te donne de vrais serveurs avec catégories, salons textuels/vocaux/de conférence, rôles, permissions par salon et modèles de communauté prêts à l'emploi : un clan, une classe ou le cercle d'un créateur peut se lancer de façon organisée en quelques minutes.",
  "Most friend groups feel settled within two weeks of moving evening voice.": "La plupart des groupes d'amis ont trouvé leurs marques dans les deux semaines suivant le passage du vocal du soir.",
  "Most groups dual-stack for a month, then realize 90% of pings happen on Descall. That’s a healthy Discord replacement path, no big-bang migration required.": "La plupart des groupes utilisent les deux pendant un mois, puis réalisent que 90 % des mentions se passent sur Descall. C'est une façon saine de remplacer Discord, sans migration brutale.",
  "Most groups want both. Descall pairs DMs and servers with the same voice stack so you are not juggling two apps.": "La plupart des groupes veulent les deux. Descall associe MP et serveurs à la même technologie vocale, pour ne pas jongler entre deux applis.",
