  "Passwords are hashed server-side. Google sign-in is available where configured. Keep your credentials private and sign out on shared devices.": "Les mots de passe sont hachés côté serveur. La connexion avec Google est disponible là où elle est configurée. Garde tes identifiants privés et déconnecte-toi sur les appareils partagés.",
  "Passwords are hashed with bcrypt. Optional email 2FA and Google sign-in are available where configured. Session management lets you revoke devices. Keep credentials private on shared computers.": "Les mots de passe sont hachés avec bcrypt. L'A2F facultative par e-mail et la connexion avec Google sont disponibles là où elles sont configurées. La gestion des sessions te permet de révoquer des appareils. Garde tes identifiants privés sur les ordinateurs partagés.",
