  "People in voice": "Personnes en vocal",
  "People saying “apps like Discord” usually want chat + persistent groups + voice. Some also want screen share. Descall covers that core. It does not try to clone every Discord bot and Stage feature, and that focus is the product.": "Ceux qui cherchent des « applis comme Discord » veulent en général du chat + des groupes permanents + du vocal. Certains veulent aussi le partage d'écran. Descall couvre cet essentiel. Il n'essaie pas de cloner chaque bot ni la fonction Conférence de Discord, et cette concentration, c'est le produit.",
