  "Pick Descall for nightly friend voice and servers without Nitro. Keep Discord if you still depend on a large bot marketplace or huge public servers.": "Choisis Descall pour le vocal du soir entre amis et des serveurs sans Nitro. Garde Discord si tu dépends encore d'une grande marketplace de bots ou d'énormes serveurs publics.",
  "Pick Descall when your group wants a lighter Discord alternative for chat, voice, and screen share. Keep Discord when you still run large public communities and bots.": "Choisis Descall quand ton groupe veut une alternative plus légère à Discord pour le chat, le vocal et le partage d'écran. Garde Discord si tu gères encore de grandes communautés publiques et des bots.",
  "Pick Gaming, Friends, or Community templates so roles and staff rooms appear ready. Invite codes replace Discord’s invite links.": "Choisis les modèles Gaming, Amis ou Communauté pour que les rôles et les salons staff soient prêts. Les codes d'invitation remplacent les liens d'invitation de Discord.",
