  "Voice-first classics. Weak for modern chat, presence, and mobile.": "Les classiques du vocal. Faibles pour le chat moderne, la présence et le mobile.",
  "Voice/video and screen share for hangouts": "Vocal/vidéo et partage d'écran pour se retrouver",
  "Volume": "Volume",
  "Waiting for others to join…": "En attente des autres participants…",
