  "Waiting…": "En attente…",
  "Want a voice chat alternative to Discord without Nitro friction? Descall uses WebRTC voice/video with TURN support, incoming-call UX, PiP, and screen-share quality presets, free for core communication.": "Tu veux une alternative de chat vocal à Discord sans les contraintes de Nitro ? Descall utilise le vocal/vidéo WebRTC avec prise en charge de TURN, une interface d'appel entrant, le PiP et des préréglages de qualité pour le partage d'écran, gratuitement pour la communication de base.",
  "Warn": "Avertir",
  "Warning": "Avertissement",
  "Watching": "Regarde",
  "Watching something": "Regarde quelque chose",
  "Watching this flip…": "Tu regardes ce lancer…",
  "Watching this hand…": "Tu regardes cette main…",
  "Watching this spin…": "Tu regardes ce tirage…",
  "We are (players already)": "Nous sommes (joueurs déjà présents)",
  "We care about your privacy": "Nous tenons à ta vie privée",
  "We don’t claim Discord’s bot marketplace, Stage events, or every platform client. Honesty ranks better than doorway pages.": "Nous ne prétendons pas avoir la marketplace de bots de Discord, les événements Conférence ou un client pour chaque plateforme. L'honnêteté vaut mieux que les pages satellites.",
  "We focus on real-time messaging, group voice/video, screen share, and a polished desktop experience, without turning private chats into SEO landings.": "Nous nous concentrons sur la messagerie en temps réel, le vocal/vidéo de groupe, le partage d'écran et une expérience de bureau soignée, sans transformer les discussions privées en pages SEO.",
  "We got your note. We’ll reply at the email you gave.": "Nous avons bien reçu ton message. Nous te répondrons à l'adresse e-mail indiquée.",
  "We now ask everyone for their date of birth so we can keep Descall safe and show the right features for your age.": "Nous demandons désormais à tout le monde sa date de naissance pour assurer la sécurité de Descall et proposer les fonctionnalités adaptées à ton âge.",
  "We only use essential cookies; we ask for your permission for analytics.": "Nous n'utilisons que les cookies essentiels ; nous te demandons ton accord pour la mesure d'audience.",
  "We only use the cookies Descall needs to run. We ask for your permission for analytics cookies.": "Nous n'utilisons que les cookies nécessaires au fonctionnement de Descall. Nous te demandons ton accord pour les cookies de mesure d'audience.",
  "We review every submission and use it to make Descall better.": "Nous lisons chaque envoi et nous en servons pour améliorer Descall.",
  "We scored apps on free core chat/calls, voice quality path, server tools, desktop/mobile reality, and whether friend groups can switch in a week, not on who has the longest feature checklist.": "Nous avons noté les applis sur la gratuité du chat et des appels de base, la qualité du vocal, les outils de serveur, la réalité sur ordinateur et mobile, et la possibilité pour un groupe d'amis de changer en une semaine, pas sur la plus longue liste de fonctionnalités.",
  "We sent a 6-digit code to your email.": "Nous avons envoyé un code à 6 chiffres à ton adresse e-mail.",
  "We use infrastructure providers (hosting, database, authentication) as processors. Content you send is visible to the recipients you choose (DMs, groups).": "Nous faisons appel à des prestataires d'infrastructure (hébergement, base de données, authentification) en tant que sous-traitants. Le contenu que tu envoies est visible par les destinataires que tu choisis (MP, groupes).",
  "We use this data to provide chat and calls, keep the service secure, improve reliability, and communicate important product updates. We do not sell your personal information.": "Nous utilisons ces données pour fournir le chat et les appels, sécuriser le service, améliorer sa fiabilité et communiquer les mises à jour importantes du produit. Nous ne vendons pas tes informations personnelles.",
  "We'll send a code to this email to verify it. It keeps your account safe: recovery, sign-in codes and two-factor authentication.": "Nous allons envoyer un code à cette adresse pour la vérifier. Cela protège ton compte : récupération, codes de connexion et authentification à deux facteurs.",
  "Weak": "Faible",
  "Weak connection": "Connexion faible",
  "Wear": "Porter",
  "Wear it right after buying": "Le porter dès l'achat",
  "Web + Windows + Android so members can join anywhere": "Web + Windows + Android pour que les membres puissent rejoindre de n'importe où",
  "Web / desktop / mobile FCM": "Web / bureau / FCM mobile",
  "Web and API traffic use HTTPS/TLS. Real-time media uses WebRTC with DTLS/SRTP between peers when a call is established.": "Le trafic web et API utilise HTTPS/TLS. Les médias en temps réel utilisent WebRTC avec DTLS/SRTP entre les participants une fois l'appel établi.",
  "Web and API traffic use HTTPS/TLS. Real-time media uses WebRTC with DTLS/SRTP between peers when a call is established. Descall does not claim default end-to-end encryption for all message history stored on the server, messages are encrypted in transit and stored so your devices can load chat history.": "Le trafic web et API utilise HTTPS/TLS. Les médias en temps réel utilisent WebRTC avec DTLS/SRTP entre les participants une fois l'appel établi. Descall ne prétend pas chiffrer de bout en bout par défaut tout l'historique des messages stocké sur le serveur : les messages sont chiffrés en transit et stockés pour que tes appareils puissent charger l'historique du chat.",
  "Web app": "Application web",
  "WebRTC": "WebRTC",
  "WebRTC voice for DMs, groups, and server lobbies with noise controls when you need them.": "Vocal WebRTC pour les MP, les groupes et les lobbies de serveur, avec réduction du bruit quand tu en as besoin.",
  "WebRTC voice/video with TURN support, incoming call UX, PiP, and screen-share quality controls. A lighter Discord alternative when you want clean calls inside servers or DMs.": "Vocal/vidéo WebRTC avec prise en charge de TURN, interface d'appel entrant, PiP et contrôle de la qualité du partage d'écran. Une alternative plus légère à Discord quand tu veux des appels nets dans les serveurs ou les MP.",
  "Websites like Discord": "Sites comme Discord",
  "Websites like Discord vs installable apps": "Sites comme Discord vs applis à installer",
  "Week 1: create a Descall group and move evening voice. Week 2: move media sharing and your gaming server if you play together. Most friend groups don’t need a full export, they need a new habit.": "Semaine 1 : crée un groupe Descall et passe-y le vocal du soir. Semaine 2 : déplace le partage de médias et ton serveur gaming si vous jouez ensemble. La plupart des groupes d'amis n'ont pas besoin d'un export complet, ils ont besoin d'une nouvelle habitude.",
  "Week 1: create a Descall group, move evening voice. Week 2: move your server and screen-share sessions. Keep Discord for public servers you still enjoy.": "Semaine 1 : crée un groupe Descall, passe-y le vocal du soir. Semaine 2 : déplace ton serveur et tes sessions de partage d'écran. Garde Discord pour les serveurs publics que tu apprécies encore.",
