  "Windows installer and the Android APK. The browser app is the same account, with no install.": "Installateur Windows et APK Android. L'application dans le navigateur utilise le même compte, sans installation.",
  "Windows installer plus Android builds, or use the full web app in the browser.": "Installateur Windows et versions Android, ou utilise l'appli web complète dans le navigateur.",
  "Windows users should install the desktop client for fewer browser tab mishaps. Android and web cover the rest of the group.": "Sur Windows, installe le client de bureau pour éviter les soucis d'onglets de navigateur. Android et le web couvrent le reste du groupe.",
  "Won": "Gagné",
  "Work-first chat. Huddles exist, but gamers looking for a Discord alternative usually want evenings, not tickets.": "Un chat pensé pour le travail. Les Huddles existent, mais les gamers qui cherchent une alternative à Discord veulent des soirées, pas des tickets.",
